def post(a, r):
    # f[s]: length of the maximal strictly increasing run starting at s
    f = [None] * N
    f[N - 1] = a[N - 1] * 0 + 1
    for s in range(N - 2, -1, -1):
        f[s] = If(a[s] < a[s + 1], 1 + f[s + 1], 1)

    # Length of the run starting at r
    Lr = f[N - 1]
    for s in range(N - 2, -1, -1):
        Lr = If(r == s, f[s], Lr)

    # s is a run start iff s == 0 or a[s-1] >= a[s]
    def is_start_formula(s):
        if s == 0:
            return r == 0
        return And(r == s, a[s - 1] >= a[s])

    # r must be a run start
    r_is_start = Or([is_start_formula(s) for s in range(N)])

    # For every run start s: f[s] <= Lr, and on ties s <= r
    conds = []
    for s in range(N):
        c = And(f[s] <= Lr, Implies(f[s] == Lr, s <= r))
        if s == 0:
            conds.append(c)
        else:
            conds.append(Implies(a[s - 1] >= a[s], c))

    return And(0 <= r, r < N, r_is_start, And(conds))
